div.script:
(function() {
    var video = document.getElementById('hls-player');
    var streamUrl = '';

    if (video && streamUrl) {
        // Check if browser supports HLS natively (Safari, iOS)
        if (video.canPlayType('application/vnd.apple.mpegurl')) {
            video.src = streamUrl;
        } 
        // Use HLS.js for other browsers
        else if (typeof Hls !== 'undefined') {
            var hls = new Hls();
            hls.loadSource(streamUrl);
            hls.attachMedia(video);
            hls.on(Hls.Events.MANIFEST_PARSED, function() {
                video.play();
            });
        } else {
            // Fallback: try to load HLS.js library
            var script = document.createElement('script');
            script.src = 'https://cdn.jsdelivr.net/npm/hls.js@latest';
            script.onload = function() {
                var hls = new Hls();
                hls.loadSource(streamUrl);
                hls.attachMedia(video);
                hls.on(Hls.Events.MANIFEST_PARSED, function() {
                    video.play();
                });
            };
            document.head.appendChild(script);
        }
    }
})();

(function() {
    var img = document.getElementById('http-image-stream');
    var streamUrl = '';

    console.log('HTTP Image/MJPEG Stream initialized');
    console.log('Stream URL:', streamUrl);

    if (img && streamUrl) {
        // For MJPEG streams (video.cgi), browser handles it automatically
        // For snapshots, refresh every 1-2 seconds for live view
        var isMJPEG = streamUrl.includes('video.cgi') || streamUrl.includes('mjpeg');
        if (!isMJPEG) {
            // Auto-refresh snapshot every 1.5 seconds
            var refreshInterval = setInterval(function() {
                try {
                    var timestamp = new Date().getTime();
                    var separator = streamUrl.indexOf('?') !== -1 ? '&' : '?';
                    // Add cache buster to force reload
                    img.src = streamUrl + separator + '_t=' + timestamp;
                } catch(err) {
                    console.error('Error refreshing image:', err);
                }
            }, 1500);

            // Clear interval if image fails to load
            img.addEventListener('error', function() {
                clearInterval(refreshInterval);
            });
        }

        img.addEventListener('error', function(e) {
            console.error('Image/MJPEG load error:', e);
            console.error('Stream URL:', streamUrl);
            console.error('Error details:', {
                naturalWidth: img.naturalWidth,
                naturalHeight: img.naturalHeight,
                complete: img.complete,
                src: img.src
            });

            // Check if it's a proxy URL and test it
            if (streamUrl.includes('/proxy/')) {
                fetch(streamUrl)
                    .then(function(response) {
                        console.log('Proxy response status:', response.status);
                        console.log('Proxy response headers:', response.headers);
                        return response.text();
                    })
                    .then(function(text) {
                        console.log('Proxy response body (first 200 chars):', text.substring(0, 200));
                    })
                    .catch(function(err) {
                        console.error('Proxy fetch error:', err);
                    });
            }

            // Show error message in the container
            var existingError = img.parentNode.querySelector('.alert-danger');
            if (!existingError) {
                var errorMsg = document.createElement('div');
                errorMsg.className = 'alert alert-danger mt-2';
                errorMsg.innerHTML = '<strong>Stream Error:</strong> Unable to load camera stream. <br/>' +
                    '<small>URL: ' + streamUrl + '</small><br/>' +
                    '<small>Check browser console (F12) for detailed error information.</small>' +
                    '<br/><small>Possible causes: Camera offline, incorrect URL, authentication failed, or network issue.</small>';
                img.parentNode.appendChild(errorMsg);
            }
        });

        img.addEventListener('load', function() {
            console.log('Image/MJPEG stream loaded successfully');
            // Remove any error messages if image loads
            var errorMsg = img.parentNode.querySelector('.alert-danger');
            if (errorMsg) {
                errorMsg.remove();
            }
        });
    }
})();

(function() {
    var video = document.getElementById('http-player');
    var streamUrl = '';

    console.log('HTTP Player initialized');
    console.log('Stream URL:', streamUrl);
    console.log('Stream Type:', '');

    if (video && streamUrl) {
        video.src = streamUrl;

        video.addEventListener('error', function(e) {
            console.error('Video error:', e);
            console.error('Error code:', video.error ? video.error.code : 'unknown');
            console.error('Stream URL:', streamUrl);
            // Try alternative: use img tag for MJPEG or snapshot
            if (video.error && video.error.code === 4) {
                console.log('Trying image fallback...');
                var img = document.createElement('img');
                img.src = streamUrl;
                img.style.cssText = 'width: 100%; height: 600px; object-fit: contain; background: #000;';
                video.parentNode.replaceChild(img, video);
            }
        });

        video.addEventListener('loadedmetadata', function() {
            console.log('Video metadata loaded');
            console.log('Video duration:', video.duration);
            console.log('Video dimensions:', video.videoWidth + 'x' + video.videoHeight);
        });

        video.addEventListener('canplay', function() {
            console.log('Video can play');
            video.play().catch(function(err) {
                console.error('Play error:', err);
            });
        });

        video.addEventListener('loadstart', function() {
            console.log('Video load started');
        });

        // Try to load the video
        video.load();
    } else {
        console.error('Video element or stream URL not found');
        if (!video) console.error('Video element not found');
        if (!streamUrl) console.error('Stream URL is empty');
    }
})();
